::: {.cell layout-align="center"}

```{.r .cell-code}
sil <- silhouette(km3$cluster, dist(lab_scaled))

plot(
  sil,
  col = c("steelblue", "firebrick", "forestgreen"),
  main = "Silhouette Plot (k = 3)",
  border = NA
)
cat("Average silhouette width:", round(mean(sil[, 3]), 3), "\n")
```

